import interp
s=open('eval.scm').read()
t=interp.tokenize(s)
d=0
for i,x in enumerate(t):
    if x=='(':d+=1
    elif x==')':
        d-=1
        if d<0:
            print('neg at token',i, x); break
print('final depth',d,'tokens',len(t))
# find location by line
d=0
for ln,line in enumerate(s.splitlines(),1):
    for tok in interp.tokenize(line):
        if tok=='(':d+=1
        elif tok==')':d-=1
    if ln>=175 and ln<=225: print(ln,d,line[:60])
EOF
